import React, { useState, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import '../../components/RealtimeWorkspace.css'; 

const ATSModule = () => {
  const context = useOutletContext(); 
  
  // SAFE DETECTOR: Handle both array format [data, setter] and object format {data, setter}
  const resumeData = Array.isArray(context) ? context[0] : context?.resumeData;
  const setResumeData = Array.isArray(context) ? context[1] : context?.setResumeData;

  const [loading, setLoading] = useState(false);
  const [localAnalysis, setLocalAnalysis] = useState(null);

  useEffect(() => {
    if (resumeData) {
      setLocalAnalysis(resumeData);
    }
  }, [resumeData]);

  const handleUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    setLoading(true);
    const formData = new FormData();
    formData.append("file", file);
        
    try {
      const response = await fetch('http://localhost:8000/api/ats/optimize', {
        method: 'POST',
        body: formData,
      });
      const data = await response.json();
      
      setLocalAnalysis(data);
      
      if (setResumeData) {
        setResumeData(data); 
      } else {
        console.error("ERROR: MainLayout context setter is unavailable.");
      }
      
    } catch (error) {
      console.error("Upload failed:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="ats" links={["Async", "Skill", "Similarity", "DB"]} />
      
      <div className="metrics-grid">
        <div className="metric-card">
          <p>SUCCESS RATE</p>
          <h4>{localAnalysis ? `${localAnalysis.score}%` : "--"}</h4>
        </div>
        <div className="metric-card">
          <p>LATENCY</p>
          <h4>{localAnalysis ? `${localAnalysis.latency}ms` : "--"}</h4>
        </div>
        <div className="metric-card">
          <p>STATUS</p>
          <h4 style={{ color: localAnalysis ? '#22c55e' : '#94a3b8' }}>
            ● {localAnalysis ? "Optimized" : "Standby"}
          </h4>
        </div>
      </div>

      <header className="workspace-header">
        <h2 style={{ color: '#1e293b' }}>ATS Optimization Engine</h2>
      </header>

      <div className="input-section">
        <label className="workspace-button" style={{ display: 'inline-block', cursor: 'pointer' }}>
            {loading ? 'Analyzing...' : 'Upload Resume'}
            <input type="file" onChange={onChange => handleUpload(onChange)} style={{ display: 'none' }} />
        </label>
      </div>

      <div className="telemetry-log">
        <p>{'>'} ATS Engine ready...</p>
        {loading && <p>{'>'} Parsing candidate data...</p>}
        {localAnalysis && <p>{'>'} Optimization complete. Score: {localAnalysis.score}%</p>}
      </div>

      {localAnalysis && (
        <div className="summary-box">
          <h3>ATS Analysis Report</h3>
          <pre>{JSON.stringify(localAnalysis, null, 2)}</pre>
        </div>
      )}
    </div>
  );
};

export default ATSModule;
